// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC (one line per drawn element)
   nozzle        -> CylinderGeometry r.16 L.65  #B0B0B0 + black edges
   chamber       -> CylinderGeometry r.55 L5.0  #E8E8E8 op.4 doubleSide + edges
   chamber cap   -> SphereGeometry hemisphere r.55 (-X end)
   heater coil   -> TubeGeometry over 6-turn helix r.28          #B5651D
   sample cloud  -> 15 x SphereGeometry(.07)                     #2E9AA0
   e-gun block   -> BoxGeometry .35x.9x.35                       #4A4A4A
   e-rays        -> 5 x CylinderGeometry r.02 (fan)              #F2A93B
   lens 1 / 2    -> CircleGeometry r.5 normal +X op.55 + dark triangular aperture
   ion paths     -> 5 x TubeGeometry over integrated arc polyline #2A9AA5
   magnet poles  -> 2 x CylinderGeometry r.75 L2.2 coaxial       #C9C9C9 + dark inner cap disks
   field slab    -> BoxGeometry 1.35 x 2.1 x 1.7 (⊥ pole axis)   #A986B8 op.35
   flight tube   -> CylinderGeometry r.62 L3.23 at -21.8°        #E8E8E8 op.4
   detector      -> CircleGeometry r.55 + ring + aperture circle #C6CE8B
   leaders       -> LineSegments black, one per text label
   chart axes    -> LineSegments black + gridlines #CCCCCC
   bars          -> 5 x BoxGeometry .22 x h x .12                #3FB3B8 / #5BC4C4
*/

const TAU = Math.PI * 2;
const ZAX = new THREE.Vector3(0, 0, 1);
const outlineMat = new THREE.LineBasicMaterial({ color: 0x1a1a1a });
const thinMat = new THREE.LineBasicMaterial({ color: 0x111111 });

scene.add(new THREE.AmbientLight(0xffffff, 0.85));
const dl = new THREE.DirectionalLight(0xffffff, 0.45);
dl.position.set(1, 2, 3);
scene.add(dl);

const instrument = new THREE.Group();
const chart = new THREE.Group();
scene.add(instrument, chart);

/* ---------- helpers ---------- */
function glassMat() {
  return new THREE.MeshBasicMaterial({
    color: 0xE8E8E8, transparent: true, opacity: 0.4,
    depthWrite: false, side: THREE.DoubleSide
  });
}
function addEdges(mesh, geom, mat) {
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geom, 25), mat || outlineMat));
}
function cylBetween(p1, p2, r, mat, seg, edges) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const h = dir.length();
  const g = new THREE.CylinderGeometry(r, r, h, seg || 32, 1, false);
  const m = new THREE.Mesh(g, mat);
  m.position.copy(p1).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  if (edges !== false) addEdges(m, g);
  return m;
}
function diskAt(center, normal, r, color, opacity, edge) {
  const g = new THREE.CircleGeometry(r, 48);
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color: color, transparent: opacity < 1, opacity: opacity,
    side: THREE.DoubleSide, depthWrite: opacity >= 1
  }));
  m.position.copy(center);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal.clone().normalize());
  if (edge) {
    const pts = [];
    for (let i = 0; i <= 64; i++) pts.push(new THREE.Vector3(r * Math.cos(i / 64 * TAU), r * Math.sin(i / 64 * TAU), 0));
    m.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), outlineMat));
  }
  return m;
}

/* ---------- chamber + inlet ---------- */
const chamber = cylBetween(new THREE.Vector3(-3.5, 0, 0), new THREE.Vector3(1.5, 0, 0), 0.55, glassMat(), 40);
instrument.add(chamber);
registerInteractive(chamber, { title: 'Ionization / acceleration chamber', tooltip: 'Evacuated chamber', body: 'The sample is vaporized, ionized and accelerated inside this evacuated tube before entering the magnetic analyzer.' });

const capG = new THREE.SphereGeometry(0.55, 32, 14, 0, TAU, 0, Math.PI / 2);
const cap = new THREE.Mesh(capG, glassMat());
cap.position.set(-3.5, 0, 0);
cap.rotation.z = Math.PI / 2;
instrument.add(cap);

const grayMat = new THREE.MeshLambertMaterial({ color: 0xB0B0B0 });
const nozzle = cylBetween(new THREE.Vector3(-4.3, 0, 0), new THREE.Vector3(-3.62, 0, 0), 0.16, grayMat, 24);
instrument.add(nozzle);
registerInteractive(nozzle, { title: 'Sample inlet', tooltip: 'Sample enters here', body: 'A tiny amount of sample is admitted into the evacuated instrument through this inlet.' });

/* ---------- heater coil ---------- */
const helixPts = [];
for (let i = 0; i <= 160; i++) {
  const t = i / 160, a = t * TAU * 6;
  helixPts.push(new THREE.Vector3(-3.4 + 0.8 * t, 0.2 + 0.28 * Math.sin(a), 0.28 * Math.cos(a)));
}
const coil = new THREE.Mesh(
  new THREE.TubeGeometry(new THREE.CatmullRomCurve3(helixPts), 220, 0.045, 8, false),
  new THREE.MeshLambertMaterial({ color: 0xB5651D })
);
instrument.add(coil);
registerInteractive(coil, { title: 'Heater', tooltip: 'Heater vaporizes sample', body: 'A resistive coil heats the sample until it vaporizes into free gaseous atoms.' });

/* ---------- sample cloud ---------- */
const cloud = new THREE.Group();
const cloudMat = new THREE.MeshLambertMaterial({ color: 0x2E9AA0 });
let seed = 7;
function rnd() { seed = (seed * 9301 + 49297) % 233280; return seed / 233280 - 0.5; }
const cloudPts = [];
for (let i = 0; i < 15; i++) {
  const p = new THREE.Vector3(-3.0 + rnd() * 0.62, -0.15 + rnd() * 0.3, rnd() * 0.3);
  cloudPts.push(p);
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 10), cloudMat);
  s.position.copy(p);
  cloud.add(s);
}
instrument.add(cloud);
registerInteractive(cloud, { title: 'Vaporized sample', tooltip: 'Gaseous atoms', body: 'Neutral gaseous atoms of the sample, ready to be ionized.' });

/* ---------- electron beam source ---------- */
const gunG = new THREE.BoxGeometry(0.35, 0.9, 0.35);
const gun = new THREE.Mesh(gunG, new THREE.MeshLambertMaterial({ color: 0x4A4A4A }));
gun.position.set(-2.6, -1.1, 0);
addEdges(gun, gunG);
instrument.add(gun);
registerInteractive(gun, { title: 'Electron beam source', tooltip: 'Electron gun', body: 'High-energy electrons knock an electron off each atom, producing 1+ cations that can be steered by electric and magnetic fields.' });

const rayMat = new THREE.MeshBasicMaterial({ color: 0xF2A93B });
for (let i = 0; i < 5; i++) {
  const tgt = new THREE.Vector3(-3.25 + i * 0.26, -0.13, (i - 2) * 0.05);
  instrument.add(cylBetween(new THREE.Vector3(-2.62, -0.62, 0), tgt, 0.022, rayMat, 8, false));
}

/* ---------- accelerating lenses ---------- */
