function computePath(idx, B) {
  const R = radiusFor(MASSES[idx], B);
  const p = new THREE.Vector3(-2.9, Y0[idx], 0);
  const dir = new THREE.Vector3(1, 0, 0);
  const pts = [p.clone()];
