    document.getElementById(id).classList.toggle('active', nm === name);
  });
}

/* ---------- labels ---------- */
function L(t, x, y, o) { return addLabel(t, new THREE.Vector3(x, y, 0), o || {}); }
L('Sample<br>enters here', -4.75, 2.72);
L('Heater vaporizes<br>sample', -2.95, 2.78);
L('Electron beam<br>source', -3.1, -2.55);
L('Ions accelerated', -1.35, -1.9);
L('Magnet', 1.78, 3.72);
L('Magnetic field<br>deflects lightest<br>ions most', 1.15, -3.02);
L('Detector', 4.5, -2.88);

L('<b>Mass-to-charge ratio</b>', CX0 + CW / 2, CY0 - 0.62, { fontSize: '12px' });
L('<span style="display:inline-block;transform:rotate(-90deg)"><b>Relative abundance (%)</b></span>', CX0 - 0.78, CY0 + CH / 2, { fontSize: '12px' });
[0, 50, 100].forEach(function (v) { L(String(v), CX0 - 0.26, cy(v), { fontSize: '12px' }); });
MASSES.forEach(function (m) { L(String(m), cx(m), CY0 - 0.27, { fontSize: '12px' }); });
const barLabels = MASSES.map(function (m, i) {
  return L('Zr-' + m, cx(m), CY0 + ABUND[i] / 100 * CH + 0.24, { fontSize: '11px' });
});
for (let i = 0; i < 5; i++) {
  const e = L('m/z = ' + MASSES[i], 0, 0, { fontSize: '11px', color: '#00707A', bold: true, background: 'rgba(255,255,255,0.85)', offset: [58, -14] });
  e.div.style.opacity = '0';
  impactLabels.push(e);
}
function setLabelVisible(e, v) { e.div.style.opacity = v ? '1' : '0'; }

/* ---------- state + updates ---------- */
let currentB = 1.0;
let selected = -1;

function updateBeams() {
  const B = currentB;
  let focus = -1, best = 0.04;
  MASSES.forEach(function (m, i) {
    const dd = Math.abs(B - focusB(m));
    if (dd < best) { best = dd; focus = i; }
  });
  for (let i = 0; i < 5; i++) {
    const res = computePath(i, B);
    const old = beams[i].geometry;
    if (res.pts.length >= 2) {
      beams[i].geometry = new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(res.pts), Math.max(8, res.pts.length), 0.028, 6, false);
    }
    if (old) old.dispose();
    const dim = selected >= 0 && selected !== i;
    beams[i].material.opacity = dim ? 0.15 : 1;
    beams[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
    if (res.hit) {
      impacts[i].position.copy(res.hit);
      impactLabels[i].pos.copy(res.hit);
    }
    impacts[i].visible = !!res.hit && !dim;
    impacts[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
    impacts[i].scale.setScalar(i === focus ? 1.6 : 1);
    setLabelVisible(impactLabels[i], !!res.hit && !dim && (i === focus || i === selected));
    bars[i].material.color.set(i === focus ? 0x00707A : BAR_BASE[i]);
    barOutlines[i].visible = (i === selected);
  }
  const r = document.getElementById('readout');
  r.innerHTML = focus >= 0
    ? '<b>Zr-' + MASSES[focus] + '</b> is focused on the detector (' + ABUND[focus] + '% abundant).'
    : 'No isotope is focused — ions strike the tube wall. Tune B toward 0.88 / 0.94 / 1.00 / 1.15 / 1.35.';
}

function setB(v, fromSlider) {
  currentB = v;
  document.getElementById('bVal').textContent = v.toFixed(2);
  if (!fromSlider) document.getElementById('fieldStrength').value = String(v);
  updateBeams();
}
function selectIsotope(i) {
  selected = (selected === i) ? -1 : i;
  document.querySelectorAll('#isoBtns button').forEach(function (b) {
    b.classList.toggle('active', Number(b.dataset.iso) === selected);
  });
  updateBeams();
}

/* ---------- UI wiring ---------- */
document.getElementById('fieldStrength').addEventListener('input', function (e) {
  bAnim = null;
  setB(parseFloat(e.target.value), true);
});
document.getElementById('viewInstrument').addEventListener('click', function () { applyView('Instrument'); });
document.getElementById('viewSpectrum').addEventListener('click', function () { applyView('Spectrum'); });
document.getElementById('viewBoth').addEventListener('click', function () { applyView('Side-by-side'); });
document.querySelectorAll('#isoBtns button').forEach(function (b) {
  b.addEventListener('click', function () {
    const v = Number(b.dataset.iso);
    selected = (v === -1) ? -2 : v - 1 + 1;
    selected = (v === -1) ? -1 : v;
    document.querySelectorAll('#isoBtns button').forEach(function (o) {
      o.classList.toggle('active', Number(o.dataset.iso) === selected);
    });
    updateBeams();
  });
});

/* ---------- demo steps ---------- */
const STEPS = [
  { title: 'Ionize and accelerate', text: 'Vapor from the heated sample is struck by the electron beam, producing cations that the two lens plates accelerate into a tight straight beam down the chamber.', view: 'Instrument', B: 0.4 },
  { title: 'The magnet bends the beam', text: 'Turn up the field: the beam enters the purple field region and fans apart. The lightest ions, Zr-90, curve the most; Zr-96 curves the least.', view: 'Instrument', B: 1.0 },
  { title: 'Focusing one isotope', text: 'At this field strength only one m/z is bent onto the detector aperture; its bar in the spectrum highlights as its ions arrive.', view: 'Side-by-side', B: 1.35 },
  { title: 'The finished spectrum', text: 'Scanning the field over all masses builds the spectrum: five peaks whose heights give the natural abundances of zirconium\'s isotopes, with Zr-90 dominant at about 51%.', view: 'Spectrum', B: 1.0 }
];
let stepIdx = -1, bAnim = null, playing = false, playTimer = 0;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('narration').textContent = s.text;
  applyView(s.view);
  bAnim = { t: 0, dur: 0.8, from: currentB, to: s.B };
}
document.getElementById('stepNext').addEventListener('click', function () { playing = false; document.getElementById('stepPlay').textContent = 'Play'; goToStep(stepIdx + 1); });
document.getElementById('stepPrev').addEventListener('click', function () { playing = false; document.getElementById('stepPlay').textContent = 'Play'; goToStep(stepIdx - 1); });
document.getElementById('stepPlay').addEventListener('click', function () {
  playing = !playing;
  this.textContent = playing ? 'Pause' : 'Play';
  if (playing) { playTimer = 0; goToStep(stepIdx + 1); }
});

/* ---------- own animation loop (tweens) ---------- */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  if (viewAnim) {
    viewAnim.t += dt;
    let k = Math.min(1, viewAnim.t / viewAnim.dur);
    k = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    controls.target.lerpVectors(viewAnim.c0, viewAnim.c1, k);
    camera.zoom = viewAnim.z0 + (viewAnim.z1 - viewAnim.z0) * k;
    camera.position.copy(controls.target).addScaledVector(viewAnim.dir, 25);
    camera.updateProjectionMatrix();
    _labelZoomRef = camera.zoom;
    controls.update();
    if (viewAnim.t >= viewAnim.dur) viewAnim = null;
  }
  if (bAnim) {
    bAnim.t += dt;
    const k = Math.min(1, bAnim.t / bAnim.dur);
    setB(bAnim.from + (bAnim.to - bAnim.from) * (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2));
    if (k >= 1) bAnim = null;
  }
  if (playing && !bAnim && !viewAnim) {
    playTimer += dt;
    if (playTimer > 3.2) { playTimer = 0; goToStep(stepIdx + 1); }
  }
}
tick();

new ResizeObserver(function () {
  if (canvas.clientWidth && canvas.clientHeight && !viewAnim) applyView(currentView, true);
}).observe(canvas);

/* ---------- init ---------- */
applyView('Instrument', true);
setB(1.0);
goToStep(0);
// @FIGURE_CODE_END

