// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC (one line per drawn element)
   nozzle          -> CylinderGeometry r.16 L.5   MeshBasic #B0B0B0 + black outline
   chamber         -> CylinderGeometry r.55 L5.0  MeshBasic #E8E8E8 op.35 doubleSide + black outline
   chamber cap     -> hemisphere SphereGeometry r.55 at -X end, same glass
   heater coil     -> TubeGeometry over 6-turn helix r.30            #B5651D
   sample cloud    -> 15 x SphereGeometry(.07)                       #2E9AA0
   e-gun block     -> BoxGeometry .35x.9x.35                         #4A4A4A + edges
   e-rays          -> 5 x thin cylinders fanning up                  #F2A93B
   lens 1 / 2      -> CircleGeometry r.5 normal +X op.62 #9B9BD0 + dark triangular aperture wedge
   ion paths       -> 5 x TubeGeometry over integrated arc polyline  #2A9AA5 (focused #00707A)
   magnet poles    -> 2 x CylinderGeometry r.75 L2.2 coaxial         #C9C9C9 flat + dark inner caps
   field slab      -> BoxGeometry 1.35 x 2.08 x 1.7 (⊥ pole axis)    #A986B8 op.33
   flight tube     -> CylinderGeometry r.62 L3.23 at -21.8°          #E8E8E8 op.35
   detector        -> CircleGeometry r.55 #C6CE8B + rim + aperture disk
   wall impacts    -> SphereGeometry .055 grey (unfocused ions)
   leaders         -> LineSegments black, one per text label
   chart panel     -> camera-facing group: axes + gridlines + 5 bars (#3FB3B8 / #5BC4C4)
*/

const TAU = Math.PI * 2;
const ZAX = new THREE.Vector3(0, 0, 1);
const INK = new THREE.LineBasicMaterial({ color: 0x1a1a1a });
const THIN = new THREE.LineBasicMaterial({ color: 0x111111 });

const instrument = new THREE.Group();
const chart = new THREE.Group();
scene.add(instrument, chart);

/* ---------- camera pose (analytic, matches axisScreenAngles below) ---------- */
const AZ = THREE.MathUtils.degToRad(69.73);
const EL = THREE.MathUtils.degToRad(12.31);
const VIEW_DIR = new THREE.Vector3(
  Math.cos(AZ) * Math.cos(EL), Math.sin(EL), Math.sin(AZ) * Math.cos(EL)).normalize();

/* ---------- helpers ---------- */
function glass() {
  return new THREE.MeshBasicMaterial({
    color: 0xE8E8E8, transparent: true, opacity: 0.35,
    depthWrite: false, side: THREE.DoubleSide
  });
}
function flat(col, op) {
  return new THREE.MeshBasicMaterial({
    color: col, transparent: op !== undefined && op < 1, opacity: op === undefined ? 1 : op,
    side: THREE.DoubleSide, depthWrite: !(op !== undefined && op < 1)
  });
}
function lineFromPts(pts, mat) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat || INK);
}
function ringLine(center, normal, r, mat) {
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal.clone().normalize());
  const pts = [];
  for (let i = 0; i <= 72; i++) {
    const a = i / 72 * TAU;
    pts.push(new THREE.Vector3(r * Math.cos(a), r * Math.sin(a), 0).applyQuaternion(q).add(center));
  }
  return lineFromPts(pts, mat);
}
function cylBetween(p1, p2, r, mat, seg) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const h = dir.length();
  const g = new THREE.CylinderGeometry(r, r, h, seg || 40, 1, true);
  const m = new THREE.Mesh(g, mat);
  m.position.copy(p1).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
// cartoon silhouette: two end rings + two side lines in the XY plane
function tubeOutline(p1, p2, r, mat) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
  const perp = new THREE.Vector3(-dir.y, dir.x, 0).normalize();
  g.add(ringLine(p1, dir, r, mat));
  g.add(ringLine(p2, dir, r, mat));
  [1, -1].forEach(function (s) {
    const o = perp.clone().multiplyScalar(r * s);
    g.add(lineFromPts([p1.clone().add(o), p2.clone().add(o)], mat));
  });
  return g;
}
function diskAt(center, normal, r, color, opacity, edge) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(r, 56), flat(color, opacity));
  m.position.copy(center);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal.clone().normalize());
  if (edge) m.add(ringLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 1), r, edge === true ? INK : edge));
  return m;
}

/* ---------- chamber + inlet ---------- */
const CH_L = new THREE.Vector3(-3.5, 0, 0), CH_R = new THREE.Vector3(1.5, 0, 0);
const chamber = cylBetween(CH_L, CH_R, 0.55, glass());
chamber.renderOrder = 3;
instrument.add(chamber);
instrument.add(tubeOutline(CH_L, CH_R, 0.55, INK));
registerInteractive(chamber, {
  title: 'Ionization / acceleration chamber', tooltip: 'Evacuated chamber',
  body: 'The sample is vaporized, ionized and accelerated inside this evacuated tube before entering the magnetic analyzer.'
});

const cap = new THREE.Mesh(new THREE.SphereGeometry(0.55, 36, 16, 0, TAU, 0, Math.PI / 2), glass());
cap.position.copy(CH_L);
cap.rotation.z = Math.PI / 2;
cap.renderOrder = 3;
instrument.add(cap);
(function () {
  const pts = [];
  for (let i = 0; i <= 40; i++) {
    const a = Math.PI / 2 + i / 40 * Math.PI;
    pts.push(new THREE.Vector3(-3.5 - 0.55 * Math.sin(a - Math.PI / 2), 0.55 * Math.cos(a - Math.PI / 2), 0));
  }
  const arc = [];
  for (let i = 0; i <= 40; i++) {
    const t = -Math.PI / 2 + i / 40 * Math.PI;
    arc.push(new THREE.Vector3(-3.5 - 0.55 * Math.cos(t), 0.55 * Math.sin(t), 0));
  }
  instrument.add(lineFromPts(arc, INK));
})();

const nozzle = cylBetween(new THREE.Vector3(-4.55, 0, 0), new THREE.Vector3(-4.0, 0, 0), 0.16, flat(0xB0B0B0), 24);
instrument.add(nozzle);
instrument.add(tubeOutline(new THREE.Vector3(-4.55, 0, 0), new THREE.Vector3(-4.0, 0, 0), 0.16, INK));
instrument.add(cylBetween(new THREE.Vector3(-4.05, 0, 0), new THREE.Vector3(-3.55, 0, 0), 0.1, flat(0xB0B0B0), 20));
registerInteractive(nozzle, {
  title: 'Sample inlet', tooltip: 'Sample enters here',
  body: 'A tiny amount of sample is admitted into the evacuated instrument through this inlet.'
});

/* ---------- heater coil ---------- */
const helixPts = [];
for (let i = 0; i <= 200; i++) {
  const t = i / 200, a = t * TAU * 6;
  helixPts.push(new THREE.Vector3(-3.4 + 0.8 * t, 0.2 + 0.3 * Math.sin(a), 0.3 * Math.cos(a)));
}
const coil = new THREE.Mesh(
  new THREE.TubeGeometry(new THREE.CatmullRomCurve3(helixPts), 260, 0.045, 8, false), flat(0xB5651D));
instrument.add(coil);
registerInteractive(coil, {
  title: 'Heater', tooltip: 'Heater vaporizes sample',
  body: 'A resistive coil heats the sample until it vaporizes into free gaseous atoms.'
});

/* ---------- vaporized sample cloud ---------- */
const cloud = new THREE.Group();
const cloudMat = flat(0x2E9AA0);
let seed = 7;
function rnd() { seed = (seed * 9301 + 49297) % 233280; return seed / 233280 - 0.5; }
for (let i = 0; i < 15; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 10), cloudMat);
  s.position.set(-3.0 + rnd() * 0.62, -0.15 + rnd() * 0.3, rnd() * 0.3);
  cloud.add(s);
}
instrument.add(cloud);
registerInteractive(cloud, {
  title: 'Vaporized sample', tooltip: 'Gaseous atoms',
  body: 'Neutral gaseous atoms of the sample, ready to be ionized by the electron beam.'
});

/* ---------- electron beam source ---------- */
const gunG = new THREE.BoxGeometry(0.35, 0.9, 0.35);
const gun = new THREE.Mesh(gunG, flat(0x4A4A4A));
gun.position.set(-2.6, -1.1, 0);
gun.add(new THREE.LineSegments(new THREE.EdgesGeometry(gunG), INK));
instrument.add(gun);
registerInteractive(gun, {
  title: 'Electron beam source', tooltip: 'Electron gun',
  body: 'High-energy electrons knock an electron off each atom, producing 1+ cations that can be steered by electric and magnetic fields.'
});
const rayMat = flat(0xF2A93B);
for (let i = 0; i < 5; i++) {
  instrument.add(cylBetween(new THREE.Vector3(-2.62, -0.62, 0),
    new THREE.Vector3(-3.25 + i * 0.26, -0.15, (i - 2) * 0.05), 0.024, rayMat, 8));
}

/* ---------- accelerating lenses ---------- */
function lensAt(x, name) {
  const disk = diskAt(new THREE.Vector3(x, 0, 0), new THREE.Vector3(1, 0, 0), 0.5, 0x9B9BD0, 0.62, true);
  disk.renderOrder = 4;
  instrument.add(disk);
  const tg = new THREE.BufferGeometry();
  tg.setAttribute('position', new THREE.Float32BufferAttribute(
    [0, 0.19, -0.06, 0, -0.19, -0.06, 0, 0.0, 0.2], 3));
  const tri = new THREE.Mesh(tg, flat(0x4a4560));
  tri.position.set(x + 0.012, 0, 0);
  tri.renderOrder = 5;
  instrument.add(tri);
  registerInteractive(disk, {
    title: name, tooltip: 'Accelerating plate',
    body: 'A charged plate with a central aperture: the electric field between the plates accelerates the cations into a narrow, fast beam.'
  });
}
lensAt(-1.6, 'First accelerating lens');
lensAt(-0.8, 'Second accelerating lens');

/* ---------- magnet poles + field slab ---------- */
const POLE_AXIS = new THREE.Vector3(1.2, 4.2, 0).normalize();
const FIELD_N = new THREE.Vector3(POLE_AXIS.y, -POLE_AXIS.x, 0).normalize();
const FIELD_CENTER = new THREE.Vector3(1.0, 0, 0);
const FIELD_T = 1.35, FIELD_H = 2.08, FIELD_D = 1.7;

function pole(cx, cy, innerSign, title) {
  const c = new THREE.Vector3(cx, cy, 0);
  const a = POLE_AXIS.clone().multiplyScalar(1.1);
  const p1 = c.clone().sub(a), p2 = c.clone().add(a);
  const m = cylBetween(p1, p2, 0.75, flat(0xC9C9C9));
  instrument.add(m);
  instrument.add(tubeOutline(p1, p2, 0.75, INK));
  const outer = innerSign > 0 ? p1 : p2;
  const inner = innerSign > 0 ? p2 : p1;
  instrument.add(diskAt(outer, POLE_AXIS, 0.75, 0xDDDDDD, 1, true));
  instrument.add(diskAt(inner.clone().addScaledVector(POLE_AXIS, -0.012 * innerSign),
    POLE_AXIS, 0.75, 0x6E5F74, 1, true));
  registerInteractive(m, {
    title: title, tooltip: 'Magnet pole',
    body: 'The two poles create a uniform magnetic field across the ion beam. The field pushes each cation onto a circular arc whose radius grows as √(m/z) and shrinks as B increases.'
  });
}
pole(1.6, 2.1, -1, 'Magnet (upper pole)');
pole(0.4, -2.1, 1, 'Magnet (lower pole)');

const slabG = new THREE.BoxGeometry(FIELD_T, FIELD_H, FIELD_D);
const slab = new THREE.Mesh(slabG, new THREE.MeshBasicMaterial({
  color: 0xA986B8, transparent: true, opacity: 0.33, depthWrite: false, side: THREE.DoubleSide
}));
slab.position.copy(FIELD_CENTER);
slab.rotation.z = Math.atan2(POLE_AXIS.y, POLE_AXIS.x) - Math.PI / 2;
slab.renderOrder = 2;
slab.add(new THREE.LineSegments(new THREE.EdgesGeometry(slabG), new THREE.LineBasicMaterial({ color: 0x8e6f9c })));
instrument.add(slab);
registerInteractive(slab, {
  title: 'Magnetic field region', tooltip: 'Magnetic field',
  body: 'Inside this region every cation follows a circular arc. Light ions have small radii and bend the most; heavy ions bend the least — so the beam fans out by mass-to-charge ratio.'
});

/* ---------- flight tube + detector ---------- */
const TUBE_START = new THREE.Vector3(1.0, -0.1, 0);
const TUBE_END = new THREE.Vector3(4.0, -1.3, 0);
const TUBE_DIR = TUBE_END.clone().sub(TUBE_START).normalize();
const TUBE_UP = new THREE.Vector3(-TUBE_DIR.y, TUBE_DIR.x, 0).normalize();
const TUBE_R = 0.62;
const flight = cylBetween(TUBE_START, TUBE_END, TUBE_R, glass());
flight.renderOrder = 3;
instrument.add(flight);
instrument.add(tubeOutline(TUBE_START, TUBE_END, TUBE_R, INK));
registerInteractive(flight, {
  title: 'Flight tube', tooltip: 'Flight tube to detector',
  body: 'The deflected ions drift down this tube in a straight line; where they land on the detector depends on how strongly the magnet bent them.'
});

const detector = diskAt(TUBE_END, TUBE_DIR, 0.55, 0xC6CE8B, 1, true);
instrument.add(detector);
instrument.add(diskAt(TUBE_END.clone().addScaledVector(TUBE_DIR, 0.012), TUBE_DIR, 0.13, 0x6f7a3f, 1, false));
registerInteractive(detector, {
  title: 'Detector', tooltip: 'Detector',
  body: 'Counts the ions arriving at each position. The signal recorded for each m/z is proportional to the natural abundance of that isotope.'
});

/* ---------- ion optics ---------- */
const MASSES = [90, 91, 92, 94, 96];
const ABUND = [51.4, 11.2, 17.1, 17.4, 2.8];
const Y0 = [-0.052, -0.026, 0, 0.026, 0.052];
