  new THREE.Vector3(-CW / 2, ly(0), 0), new THREE.Vector3(-CW / 2, ly(108), 0),
  new THREE.Vector3(-CW / 2, ly(0), 0), new THREE.Vector3(CW / 2, ly(0), 0)
];
[0, 50, 100].forEach(function (v) { axPts.push(new THREE.Vector3(-CW / 2 - 0.13, ly(v), 0), new THREE.Vector3(-CW / 2, ly(v), 0)); });
MASSES.forEach(function (m) { axPts.push(new THREE.Vector3(lx(m), ly(0), 0), new THREE.Vector3(lx(m), ly(0) - 0.13, 0)); });
chart.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(axPts), THIN));

const BAR_BASE = [0x5BC4C4, 0x3FB3B8, 0x3FB3B8, 0x3FB3B8, 0x3FB3B8];
const bars = [], barOutlines = [];
for (let i = 0; i < 5; i++) {
  const h = ABUND[i] / 100 * CH;
  const g = new THREE.BoxGeometry(0.22, h, 0.1);
  const b = new THREE.Mesh(g, flat(BAR_BASE[i]));
  b.position.set(lx(MASSES[i]), ly(0) + h / 2, 0);
  chart.add(b); bars.push(b);
  const ol = new THREE.LineSegments(new THREE.EdgesGeometry(g), new THREE.LineBasicMaterial({ color: 0x00707A }));
  ol.position.copy(b.position); ol.visible = false;
  chart.add(ol); barOutlines.push(ol);
  registerInteractive(b, {
    title: 'Zr-' + MASSES[i] + '  (' + ABUND[i] + '%)',
    tooltip: 'Click to isolate Zr-' + MASSES[i],
    body: 'Zr-' + MASSES[i] + ' makes up ' + ABUND[i] + '% of natural zirconium. Its ions are focused on the detector aperture when B ≈ ' + focusB(MASSES[i]).toFixed(2) + '.',
    onClick: function () { selectIsotope(i); }
  });
}
chart.updateMatrixWorld(true);
function chartWorld(x, y) { return new THREE.Vector3(x, y, 0).applyMatrix4(chart.matrixWorld); }

/* ---------- camera ---------- */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 4.5, z: 30 }, heightFraction: 0.85 });
camera.near = 0.1; camera.far = 300; camera.updateProjectionMatrix();
_lastViewArgs = null;

const VIEWS = {
  Instrument: { c: new THREE.Vector3(-0.1, 0.2, 0), hw: 5.7, hh: 4.15 },
  Spectrum: { c: chartWorld(-0.2, -0.05), hw: 3.05, hh: 2.6 },
  'Side-by-side': { c: new THREE.Vector3(3.0, 0.2, 0), hw: 8.6, hh: 4.15 }
};
let currentView = 'Instrument';
let viewAnim = null;
function zoomFor(hw, hh) { return Math.min((d * aspect) / hw, d / hh); }
function applyView(name, immediate) {
  currentView = name;
  const v = VIEWS[name];
  const z1 = zoomFor(v.hw, v.hh);
  const dir = camera.position.clone().sub(controls.target).normalize();
  if (immediate) {
    controls.target.copy(v.c);
    camera.zoom = z1;
    camera.position.copy(v.c).addScaledVector(dir, 30);
    camera.updateProjectionMatrix();
    _labelZoomRef = z1;
    controls.update();
    viewAnim = null;
  } else {
    viewAnim = { t: 0, dur: 0.75, c0: controls.target.clone(), c1: v.c.clone(), z0: camera.zoom, z1: z1, dir: dir };
  }
  ['viewInstrument', 'viewSpectrum', 'viewBoth'].forEach(function (id, k) {
    const nm = ['Instrument', 'Spectrum', 'Side-by-side'][k];
    document.getElementById(id).classList.toggle('active', nm === name);
  });
}

/* ---------- labels ---------- */
function L(t, x, y, o) { return addLabel(t, new THREE.Vector3(x, y, 0), o || {}); }
L('Sample<br>enters here', -4.82, 2.62);
L('Heater vaporizes<br>sample', -2.98, 2.78);
L('Electron beam<br>source', -3.18, -2.52);
L('Ions accelerated', -1.32, -1.82);
L('Magnet', 1.86, 3.74);
L('Magnetic field<br>deflects lightest<br>ions most', 1.18, -3.0);
L('Detector', 4.56, -2.88);

function CL(t, x, y, o) { return addLabel(t, chartWorld(x, y), o || {}); }
CL('<b>Mass-to-charge ratio</b>', 0, ly(0) - 0.62, { fontSize: '12px' });
CL('<span style="display:inline-block;transform:rotate(-90deg)"><b>Relative abundance (%)</b></span>',
  -CW / 2 - 0.8, 0, { fontSize: '12px' });
[0, 50, 100].forEach(function (v) { CL(String(v), -CW / 2 - 0.3, ly(v), { fontSize: '12px' }); });
MASSES.forEach(function (m) { CL(String(m), lx(m), ly(0) - 0.29, { fontSize: '12px' }); });
MASSES.forEach(function (m, i) { CL('Zr-' + m, lx(m), ly(ABUND[i]) + 0.24, { fontSize: '11px' }); });

for (let i = 0; i < 5; i++) {
  const e = L('m/z = ' + MASSES[i], 0, 0, {
    fontSize: '11px', color: '#00707A', bold: true,
    background: 'rgba(255,255,255,0.86)', offset: [60, -16]
  });
  e.div.style.opacity = '0';
  impactLabels.push(e);
}

/* ---------- state ---------- */
let currentB = 1.0;
let selected = -1;
let bAnim = null;

function updateBeams() {
  const B = currentB;
  const res = [];
  let focus = -1, best = 0.13;
  for (let i = 0; i < 5; i++) {
    const r = integrate(Y0[i], radiusFor(MASSES[i], B), false);
    res.push(r);
    if (r.hit && Math.abs(r.offset) < best) { best = Math.abs(r.offset); focus = i; }
  }
  for (let i = 0; i < 5; i++) {
    const r = res[i];
    if (r.pts.length >= 2) {
      const old = beams[i].geometry;
      beams[i].geometry = new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(r.pts), Math.max(8, Math.min(400, r.pts.length)), 0.028, 6, false);
      if (old) old.dispose();
    }
    const dim = selected >= 0 && selected !== i;
    beams[i].material.opacity = dim ? 0.16 : 1;
    beams[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
    if (r.hit) {
      impacts[i].position.copy(r.hit).addScaledVector(TUBE_DIR, 0.03);
      impactLabels[i].pos.copy(r.hit);
      impacts[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
      impacts[i].scale.setScalar(i === focus ? 1.5 : 0.95);
    }
    impacts[i].visible = !!r.hit && !dim;
    if (r.wall) wallHits[i].position.copy(r.wall);
    wallHits[i].visible = !!r.wall && !dim;
    impactLabels[i].div.style.opacity = (r.hit && !dim && (i === focus || i === selected)) ? '1' : '0';
    bars[i].material.color.set(i === focus ? 0x00707A : BAR_BASE[i]);
    barOutlines[i].visible = (i === selected);
  }
  const arrived = res.filter(function (r) { return !!r.hit; }).length;
  const ro = document.getElementById('readout');
  if (focus >= 0) {
    ro.innerHTML = '<b>Zr-' + MASSES[focus] + '</b> is centred on the detector aperture (' +
      ABUND[focus] + '% abundant). ' + arrived + '/5 beams reach the detector.';
  } else if (arrived > 0) {
    ro.innerHTML = arrived + '/5 beams reach the detector, but none is centred on the aperture yet.';
  } else {
    ro.innerHTML = 'The field is too ' + (B < 1 ? 'weak' : 'strong') +
      ' — every ion strikes the tube wall (grey dots) before the detector.';
  }
}

function setB(v, fromSlider) {
  currentB = v;
  document.getElementById('bVal').textContent = v.toFixed(2);
  if (!fromSlider) document.getElementById('fieldStrength').value = String(v);
  updateBeams();
}
function syncIsoButtons() {
  document.querySelectorAll('#isoBtns button').forEach(function (b) {
    b.classList.toggle('active', Number(b.dataset.iso) === selected);
  });
}
function selectIsotope(i) {
  selected = (selected === i) ? -1 : i;
  syncIsoButtons();
  updateBeams();
}

/* ---------- UI wiring ---------- */
document.getElementById('focusHint').textContent =
  'Focus values: ' + MASSES.map(function (m) { return focusB(m).toFixed(2); }).join(' / ');
document.getElementById('fieldStrength').addEventListener('input', function (e) {
  bAnim = null;
  setB(parseFloat(e.target.value), true);
});
document.getElementById('viewInstrument').addEventListener('click', function () { applyView('Instrument'); });
document.getElementById('viewSpectrum').addEventListener('click', function () { applyView('Spectrum'); });
document.getElementById('viewBoth').addEventListener('click', function () { applyView('Side-by-side'); });
document.querySelectorAll('#isoBtns button').forEach(function (b) {
  b.addEventListener('click', function () {
    selected = Number(b.dataset.iso);
    syncIsoButtons();
    updateBeams();
  });
});

/* ---------- guided tour ---------- */
const STEPS = [
  {
    title: 'Ionize and accelerate', view: 'Instrument', B: 0.55,
    text: 'Vapor from the heated sample is struck by the electron beam, producing cations that the two lavender lens plates accelerate into a tight straight beam. With the field this weak the ions barely bend and strike the flight-tube wall.'
  },
  {
    title: 'The magnet bends the beam', view: 'Instrument', B: 1.0,
    text: 'Turn up the field: the beam crosses the purple field region and fans apart. Zr-90, the lightest, curves the most and lands lowest; Zr-96 curves the least. All five now reach the detector.'
  },
  {
    title: 'Focusing one isotope', view: 'Side-by-side', B: focusB(94),
    text: 'At this field strength Zr-94 sits exactly on the detector aperture; its bar in the spectrum highlights as its ions arrive. Scanning B moves each isotope in turn onto the aperture.'
  },
  {
    title: 'The finished spectrum', view: 'Spectrum', B: 1.0,
    text: 'Scanning the field over all masses builds the spectrum: five peaks whose heights give the natural abundances of zirconium\'s isotopes, with Zr-90 dominant at about 51%.'
  }
];
let stepIdx = -1, playing = false, playTimer = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('narration').textContent = s.text;
  applyView(s.view);
  bAnim = { t: 0, dur: 0.8, from: currentB, to: s.B };
}
document.getElementById('stepNext').addEventListener('click', function () {
  playing = false; document.getElementById('stepPlay').textContent = 'Play'; goToStep(stepIdx + 1);
});
document.getElementById('stepPrev').addEventListener('click', function () {
  playing = false; document.getElementById('stepPlay').textContent = 'Play'; goToStep(stepIdx - 1);
});
document.getElementById('stepPlay').addEventListener('click', function () {
  playing = !playing;
  this.textContent = playing ? 'Pause' : 'Play';
  if (playing) { playTimer = 0; goToStep(stepIdx + 1); }
});

/* ---------- tween loop ---------- */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;
  if (viewAnim) {
    viewAnim.t += dt;
    let k = Math.min(1, viewAnim.t / viewAnim.dur);
    k = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    controls.target.lerpVectors(viewAnim.c0, viewAnim.c1, k);
    camera.zoom = viewAnim.z0 + (viewAnim.z1 - viewAnim.z0) * k;
    camera.position.copy(controls.target).addScaledVector(viewAnim.dir, 30);
    camera.updateProjectionMatrix();
    _labelZoomRef = camera.zoom;
    controls.update();
    if (viewAnim.t >= viewAnim.dur) viewAnim = null;
  }
  if (bAnim) {
    bAnim.t += dt;
    const k0 = Math.min(1, bAnim.t / bAnim.dur);
    const k = k0 < 0.5 ? 2 * k0 * k0 : 1 - Math.pow(-2 * k0 + 2, 2) / 2;
    setB(bAnim.from + (bAnim.to - bAnim.from) * k);
    if (k0 >= 1) bAnim = null;
  }
  if (playing && !bAnim && !viewAnim) {
    playTimer += dt;
    if (playTimer > 3.4) { playTimer = 0; goToStep(stepIdx + 1); }
  }
}
tick();

new ResizeObserver(function () {
  if (canvas.clientWidth && canvas.clientHeight && !viewAnim) applyView(currentView, true);
}).observe(canvas);

/* ---------- init: source-matching default state ---------- */
applyView('Instrument', true);
setB(1.0);
document.getElementById('stepTitle').textContent = 'Drag to orbit · press Next ▶ for the tour';
document.getElementById('narration').textContent =
  'Five teal ion beams leave the accelerator together, fan apart in the magnetic field according to their mass-to-charge ratio, and strike the detector at different heights — producing the spectrum on the right.';
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

