/* ---------- magnet poles + field region ---------- */
const POLE_AXIS = new THREE.Vector3(1.2, 4.2, 0).normalize();
const POLE_HALF = 1.1;
const UP_C = new THREE.Vector3(1.6, 2.1, 0);
const LO_C = new THREE.Vector3(0.4, -2.1, 0);
const F_LOW = LO_C.clone().addScaledVector(POLE_AXIS, POLE_HALF);
const F_HIGH = UP_C.clone().addScaledVector(POLE_AXIS, -POLE_HALF);
const FIELD_CENTER = F_LOW.clone().add(F_HIGH).multiplyScalar(0.5);
const FIELD_R = 0.76;
const FIELD_HALF = F_HIGH.distanceTo(F_LOW) * 0.5;

function pole(center, innerSign, title) {
  const a = POLE_AXIS.clone().multiplyScalar(POLE_HALF);
