/* ---------- ion optics ---------- */
const MASSES = [90, 91, 92, 94, 96];
const ABUND = [51.4, 11.2, 17.1, 17.4, 2.8];
const Y0 = [-0.052, -0.026, 0, 0.026, 0.052];
const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _c = new THREE.Vector3();

function insideEnvelope(p) {
  if (p.x >= -3.5 && p.x <= 1.6 && Math.sqrt(p.y * p.y + p.z * p.z) < 0.50) return true;
  _c.copy(p).sub(TUBE_START);
  const al = _c.dot(TUBE_DIR);
  if (al >= -0.5 && al <= 3.35) {
    const perp = Math.sqrt(Math.max(0, _c.lengthSq() - al * al));
    if (perp < TUBE_R - 0.05) return true;
  }
  return false;
}

function integrate(y0, R, ignoreWalls) {
  const p = new THREE.Vector3(-2.95, y0, 0);
  const dir = new THREE.Vector3(1, 0, 0);
  const pts = [p.clone()];
  const ds = 0.025;
  let hit = null, wall = null, offset = null;
  for (let s = 0; s < 700; s++) {
    _a.copy(p).sub(FIELD_CENTER);
    const al = _a.dot(POLE_AXIS);
    if (Math.abs(al) < FIELD_HALF) {
      const perp = Math.sqrt(Math.max(0, _a.lengthSq() - al * al));
      if (perp < FIELD_R) dir.applyAxisAngle(ZAX, -ds / R);
    }
    p.addScaledVector(dir, ds);
    _b.copy(p).sub(TUBE_END);
    if (_b.dot(TUBE_DIR) >= 0) {
      hit = p.clone(); offset = _b.dot(TUBE_UP); pts.push(hit.clone()); break;
    }
    pts.push(p.clone());
    if (!ignoreWalls && !insideEnvelope(p)) { wall = p.clone(); break; }
    if (p.x > 7 || Math.abs(p.y) > 7) break;
  }
  return { pts: pts, hit: hit, wall: wall, offset: offset };
}

function offsetForR(R) {
  const r = integrate(0, R, true);
  return r.offset === null ? (R < 5 ? -10 : 10) : r.offset;
}
// calibrate R so Zr-92 lands on the detector centre at B = 1
let R92 = 4.0;
(function () {
  let lo = 1.4, hi = 16;
  for (let i = 0; i < 50; i++) {
    const mid = 0.5 * (lo + hi);
    if (offsetForR(mid) < 0) lo = mid; else hi = mid;
  }
  R92 = 0.5 * (lo + hi);
})();
const SENS = (offsetForR(R92 * 1.03) - offsetForR(R92 * 0.97)) / 0.06;
const TARGET_SPREAD = 0.60;
let GX = 4;
for (let i = 0; i < 40; i++) {
  const sp = SENS * (Math.sqrt(1 + GX * 4 / 92) - Math.sqrt(1 + GX * -2 / 92));
  if (!(sp > 1e-6)) break;
  GX = Math.min(24, Math.max(1, GX * TARGET_SPREAD / sp));
}
function rho(m) { return Math.sqrt(Math.max(0.15, 1 + GX * (m - 92) / 92)); }
function focusB(m) { return rho(m); }
function radiusFor(m, B) { return R92 * rho(m) / B; }

const beams = [], impacts = [], wallHits = [], impactLabels = [];
for (let i = 0; i < 5; i++) {
