  const g = new THREE.Mesh(new THREE.SphereGeometry(0.075, 16, 12), flat(0x00707A));
  g.visible = false; instrument.add(g); impacts.push(g);
  const w = new THREE.Mesh(new THREE.SphereGeometry(0.055, 12, 8), flat(0x9a9a9a));
  w.visible = false; instrument.add(w); wallHits.push(w);
}

