/* ---------- view management ---------- */
function setPick(root, on) { root.traverse(function (o) { o.layers.set(on ? 0 : 1); }); }
function applyVisibility(showInstr, showChart) {
  instrument.visible = showInstr; setPick(instrument, showInstr);
  chart.visible = showChart; setPick(chart, showChart);
  instrLabels.forEach(function (e) { e.div.style.visibility = showInstr ? 'visible' : 'hidden'; });
  chartLabels.forEach(function (e) { e.div.style.visibility = showChart ? 'visible' : 'hidden'; });
}
const VIEWS = {
  Instrument: { c: new THREE.Vector3(-0.1, 0.2, 0), hw: 5.9, hh: 4.3, instr: true, chart: false },
  Spectrum: { c: chartWorld(-0.2, -0.05), hw: 3.15, hh: 2.7, instr: false, chart: true },
  'Side-by-side': { c: new THREE.Vector3(3.1, 0.2, 0), hw: 8.9, hh: 4.3, instr: true, chart: true }
};
let currentView = 'Instrument';
let viewAnim = null;
function zoomFor(hw, hh) { return Math.min((d * aspect) / hw, d / hh); }
function applyView(name, immediate) {
  const prev = VIEWS[currentView];
  currentView = name;
  const v = VIEWS[name];
  const z1 = zoomFor(v.hw, v.hh);
  const dir = camera.position.clone().sub(controls.target).normalize();
  if (immediate) {
    applyVisibility(v.instr, v.chart);
    controls.target.copy(v.c);
    camera.zoom = z1;
    camera.position.copy(v.c).addScaledVector(dir, 30);
    camera.updateProjectionMatrix();
    _labelZoomRef = z1;
    controls.update();
    viewAnim = null;
  } else {
    applyVisibility(prev.instr || v.instr, prev.chart || v.chart);
    viewAnim = { t: 0, dur: 0.75, c0: controls.target.clone(), c1: v.c.clone(), z0: camera.zoom, z1: z1, dir: dir, fin: name };
  }
  ['viewInstrument', 'viewSpectrum', 'viewBoth'].forEach(function (id, k) {
    const nm = ['Instrument', 'Spectrum', 'Side-by-side'][k];
    document.getElementById(id).classList.toggle('active', nm === name);
  });
}

/* ---------- state ---------- */
let currentB = 1.0;
let selected = -1;
let bAnim = null;

function updateBeams() {
  const B = currentB;
  const res = [];
  let focus = -1, best = 0.13;
  for (let i = 0; i < 5; i++) {
    const r = integrate(Y0[i], radiusFor(MASSES[i], B), false);
    res.push(r);
    if (r.hit && Math.abs(r.offset) < best) { best = Math.abs(r.offset); focus = i; }
  }
  for (let i = 0; i < 5; i++) {
    const r = res[i];
    if (r.pts.length >= 2) {
      const old = beams[i].geometry;
      beams[i].geometry = new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(r.pts), Math.max(8, Math.min(400, r.pts.length)), 0.027, 6, false);
      if (old) old.dispose();
    }
    const dim = selected >= 0 && selected !== i;
    beams[i].material.opacity = dim ? 0.16 : 1;
    beams[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
    if (r.hit) {
      impacts[i].position.copy(r.hit).addScaledVector(TUBE_DIR, 0.03);
      impactLabels[i].pos.copy(r.hit);
      impacts[i].material.color.set(i === focus ? 0x00707A : 0x2A9AA5);
      impacts[i].scale.setScalar(i === focus ? 1.5 : 0.95);
    }
    impacts[i].visible = !!r.hit && !dim;
    if (r.wall) wallHits[i].position.copy(r.wall);
    wallHits[i].visible = !!r.wall && !dim;
    impactLabels[i].div.style.opacity = (r.hit && !dim && (i === focus || i === selected)) ? '1' : '0';
    bars[i].material.color.set(i === focus ? 0x00707A : BAR_BASE[i]);
    barOutlines[i].visible = (i === selected);
  }
  // re-assert per-view pickability/visibility after toggling impact markers
  const v = VIEWS[currentView];
  if (viewAnim === null) { instrument.visible = v.instr; chart.visible = v.chart; }
  const arrived = res.filter(function (r) { return !!r.hit; }).length;
  const ro = document.getElementById('readout');
  if (focus >= 0) {
    ro.innerHTML = '<b>Zr-' + MASSES[focus] + '</b> is centred on the detector aperture (' +
      ABUND[focus] + '% abundant). ' + arrived + '/5 beams reach the detector.';
  } else if (arrived > 0) {
    ro.innerHTML = arrived + '/5 beams reach the detector, but none is centred on the aperture yet.';
  } else {
    ro.innerHTML = 'The field is too ' + (B < 1 ? 'weak' : 'strong') +
      ' — every ion strikes the tube wall (grey dots) before the detector.';
  }
}

function setB(v, fromSlider) {
  currentB = v;
  document.getElementById('bVal').textContent = v.toFixed(2);
  if (!fromSlider) document.getElementById('fieldStrength').value = String(v);
  updateBeams();
}
